def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_C = 0
    my_D = 0
    for m, o in history:
        if o == 'C':
            opp_C += 1
        if m == 'D':
            my_D += 1

    opp_D = n - opp_C

    if opp_C == 0:
        if n % 10 == 0:
            return 'C'
        return 'D'

    if opp_D == 0:
        if my_D > 0:
            return 'D'
        if n >= 10:
            return 'D'
        return 'C'

    window = min(10, n)
    recent = history[-window:]
    cd_count = 0
    for m, o in recent:
        if m == 'C' and o == 'D':
            cd_count += 1
    opp_coop_rate = opp_C / n
    if cd_count >= 3 and opp_coop_rate < 0.7:
        return 'D'

    my_last, opp_last = history[-1]

    opp_d_streak = 0
    for i in range(n-1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    if my_last == 'C' and opp_last == 'D':
        if n >= 2 and history[-2][0] == 'D':
            return 'C'
        if opp_coop_rate > 0.7 and opp_d_streak <= 4:
            return 'C'
        return 'D'

    if my_last == 'C' and opp_last == 'C':
        return 'C'

    if my_last == 'D' and opp_last == 'D':
        if opp_d_streak >= 3 and opp_coop_rate > 0.3:
            return 'C'
        return 'D'

    if my_last == 'D' and opp_last == 'C':
        return 'D'

    return 'C'
